#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

# A wizard calls only some of the library's helpers; the rest stay so every copy matches.
# shellcheck disable=SC2329
set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
	BOLD=$(tput bold)
	DIM=$(tput dim)
	RESET=$(tput sgr0)
	BLUE=$(tput setaf 4)
	GREEN=$(tput setaf 2)
	YELLOW=$(tput setaf 3)
else
	BOLD=""
	DIM=""
	RESET=""
	BLUE=""
	GREEN=""
	YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
	[[ -t 1 ]] || return 0
	if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
	printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
	_clear
	printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
	printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
	printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
	printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
	printf '  later, since it remembers values already saved.%s\n' "$RESET"
	pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
	_clear
	_STAGE_INDEX=$((_STAGE_INDEX + 1))
	printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
		"$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say() { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
	local url="$1"
	printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
	{
		if command -v wslview >/dev/null 2>&1; then
			wslview "$url"
		elif command -v explorer.exe >/dev/null 2>&1; then
			explorer.exe "$url"
		elif command -v xdg-open >/dev/null 2>&1; then
			xdg-open "$url"
		elif command -v open >/dev/null 2>&1; then
			open "$url"
		else false; fi
	} >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
	printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
	read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
	local reply=""
	printf '  %s? %s [y/N] ' "$YELLOW" "$1"
	read -r reply || true
	[[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
	[[ -f "$ENV_FILE" ]] || return 1
	local line value sq="'\\''"
	line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
	value="${line#*=}"
	if [[ "$value" == \'*\' ]]; then
		value="${value:1:${#value}-2}"
		value="${value//"$sq"/\'}"
	elif [[ "$value" == \"*\" ]]; then
		value="${value:1:${#value}-2}"
		[[ "$value" == *[\\\$\"]* ]] && return 1 # escapes, $ or ": can't decode safely; ask again
	fi
	printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
	local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
	current=$(_existing "$key" || true)
	# Readline needs the colour codes wrapped in \001..\002 to place the cursor.
	p="  $s$BOLD$e$prompt$s$RESET$e "
	[[ -n "$current" ]] && p+="$s$DIM${e}[Enter keeps current]$s$RESET$e "
	read -e -r -p "$p" input || rc=1
	if ((rc)) && [[ -z "$input" ]]; then return 1; fi
	[[ -z "$input" && -n "$current" ]] && input="$current"
	printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
	local key="$1" prompt="$2" current input rc=0
	current=$(_existing "$key" || true)
	if [[ -n "$current" ]]; then
		printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
	else
		printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
	fi
	read -rs input || rc=1
	printf '\n'
	if ((rc)) && [[ -z "$input" ]]; then return 1; fi
	[[ -z "$input" && -n "$current" ]] && input="$current"
	printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
	local key="$1" value="$2" tmp sq="'\\''"
	[[ -e "$ENV_FILE" ]] || (umask 077 && : >"$ENV_FILE")
	tmp=$(mktemp)
	grep -vE "^${key}=" "$ENV_FILE" >"$tmp" || true
	printf "%s='%s'\n" "$key" "${value//\'/$sq}" >>"$tmp"
	cat "$tmp" >"$ENV_FILE"
	rm -f "$tmp"
	printf -v "$key" '%s' "$value"
	WRITTEN_ENV+=("$key")
	printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
	local name="$1" value="$2"
	if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
		if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
			WRITTEN_SECRET+=("$name")
			printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
			return
		fi
	fi
	SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
	warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
	local name="$1" value="$2"
	if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
		if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
			printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
			return
		fi
	fi
	SKIPPED+=("GitHub variable $name")
	warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
	_clear
	printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
	((${#WRITTEN_ENV[@]})) && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
	((${#WRITTEN_SECRET[@]})) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
	if ((${#SKIPPED[@]})); then
		printf '\n'
		warn "still to do by hand:"
		for s in "${SKIPPED[@]}"; do note "  - $s"; done
	fi
	printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

	# wrangler reads .dev.vars when it serves /api locally.
	cd "$(git rev-parse --show-toplevel)"
	ENV_FILE=".dev.vars"
	# The old SvelteKit checkout ran this setup first; its values seed this one.
	OLD_ENV_FILE="${OLD_ENV_FILE:-$HOME/personal-projects/journal/.dev.vars}"
	WORKER="journal"
	APP_URL="https://journal.fullchee.workers.dev"
	REDIRECT_URI="http://localhost:8765"
	# calendar.events reads and writes events; calendar.freebusy reads busy time; calendar.calendarlist.readonly lists calendars for the Calendar link picker (#145).
	SCOPES="https://www.googleapis.com/auth/calendar.events https://www.googleapis.com/auth/calendar.freebusy https://www.googleapis.com/auth/calendar.calendarlist.readonly"
	NAMES=(GOOGLE_CLIENT_ID GOOGLE_CLIENT_SECRET GOOGLE_REFRESH_TOKEN)

	urlencode() { python3 -I -c 'import sys, urllib.parse; print(urllib.parse.quote(sys.argv[1], safe=""))' "$1"; }
	json_field() { python3 -I -c 'import sys, json; print(json.load(sys.stdin).get(sys.argv[1], ""))' "$1"; }

	# refresh prints Google's reply to a refresh-token exchange; the values go through stdin, not argv.
	refresh() {
		printf 'refresh_token=%s&client_id=%s&client_secret=%s&grant_type=refresh_token' \
			"$(urlencode "$GOOGLE_REFRESH_TOKEN")" "$(urlencode "$GOOGLE_CLIENT_ID")" "$(urlencode "$GOOGLE_CLIENT_SECRET")" |
			curl -sS https://oauth2.googleapis.com/token --data @-
	}

	TOTAL_STAGES=6

	banner "Google Calendar access for the journal app (#59)"

	stage "Load the saved values"
	for name in "${NAMES[@]}"; do
		value=$(_existing "$name" || true)
		if [[ -z "$value" && -f "$OLD_ENV_FILE" ]]; then
			value=$(ENV_FILE="$OLD_ENV_FILE" _existing "$name" || true)
			[[ -n "$value" ]] && write_env "$name" "$value"
		fi
		printf -v "$name" '%s' "$value"
		if [[ -n "$value" ]]; then
			printf '  %s✓ found%s %s\n' "$GREEN" "$RESET" "$name"
		else
			note "missing $name: stage 4 asks for it"
		fi
	done
	pause

	stage "Check the refresh token"
	TOKEN_OK=0
	if [[ -n "$GOOGLE_REFRESH_TOKEN" ]]; then
		response=$(refresh)
		if [[ -n "$(json_field access_token <<<"$response")" ]]; then
			TOKEN_OK=1
			printf '  %s✓ Google accepted the refresh token%s\n' "$GREEN" "$RESET"
			granted=$(json_field scope <<<"$response")
			for scope in $SCOPES; do
				[[ " $granted " == *" $scope "* ]] || {
					warn "Not granted: $scope. Get a new token at stage 4."
					TOKEN_OK=0
				}
			done
			if [[ -n "$(json_field refresh_token_expires_in <<<"$response")" ]]; then
				warn "This token expires: the app was in Testing when it was granted."
				TOKEN_OK=0
			fi
		else
			warn "Google refused the token: $(json_field error <<<"$response")"
		fi
	fi
	if ((TOKEN_OK)); then note "Stages 3 and 4 are skipped."; else note "Stages 3 and 4 get a new token."; fi
	pause

	stage "Publish the OAuth app"
	if ((TOKEN_OK)); then
		say "Skipped: the saved token works and never expires."
	else
		say "Testing mode gives tokens that expire after 7 days. Production tokens don't expire."
		open_url "https://console.cloud.google.com/auth/audience"
		step "Pick the project that owns the Journal app client (its ID starts with 709199)."
		step "If Publishing status reads Testing, click Publish app, then Confirm."
		warn "Leave Data Access scopes empty, or Google demands verification."
		if ! confirm "Does Publishing status read In production?"; then
			warn "Publish the app first: a Testing-mode token dies in 7 days."
			exit 1
		fi
		if [[ -z "$GOOGLE_CLIENT_ID" || -z "$GOOGLE_CLIENT_SECRET" ]]; then
			open_url "https://console.cloud.google.com/auth/clients/create"
			step "Application type: Web application. Name: Journal app."
			step "Authorized redirect URIs → Add URI → $REDIRECT_URI. Click Create."
			warn "Copy the client secret now: Console hides it once you close the dialog."
			ask GOOGLE_CLIENT_ID "Paste the client ID:"
			ask_secret GOOGLE_CLIENT_SECRET "Paste the client secret:"
			write_env GOOGLE_CLIENT_ID "$GOOGLE_CLIENT_ID"
			write_env GOOGLE_CLIENT_SECRET "$GOOGLE_CLIENT_SECRET"
		fi
		pause
	fi

	stage "Grant calendar access"
	if ((TOKEN_OK)); then
		say "Skipped: the saved token works."
	else
		state=$(python3 -I -c 'import secrets; print(secrets.token_urlsafe(16))')
		open_url "https://accounts.google.com/o/oauth2/v2/auth?client_id=$(urlencode "$GOOGLE_CLIENT_ID")&redirect_uri=$(urlencode "$REDIRECT_URI")&response_type=code&scope=$(urlencode "$SCOPES")&access_type=offline&prompt=consent&state=$state"
		step "Pick the personal account."
		step "On 'Google hasn't verified this app': Advanced → Go to … (unsafe)."
		step "Tick both calendar boxes, then Continue. Get a parent's approval if asked."
		step "The browser lands on a localhost page that fails to load. That's expected."
		step "Copy the full URL from the address bar."
		ask REDIRECTED_URL "Paste the URL:"
		read -r code returned_state < <(python3 -I -c '
import sys, urllib.parse
q = urllib.parse.parse_qs(urllib.parse.urlparse(sys.argv[1]).query)
print(q.get("code", [""])[0], q.get("state", [""])[0])' "$REDIRECTED_URL")
		if [[ -z "$code" || "$returned_state" != "$state" ]]; then
			warn "That URL has no code, or comes from another attempt. Re-run the wizard."
			exit 1
		fi
		response=$(curl -sS https://oauth2.googleapis.com/token \
			--data-urlencode "code=$code" \
			--data-urlencode "client_id=$GOOGLE_CLIENT_ID" \
			--data-urlencode "client_secret=$GOOGLE_CLIENT_SECRET" \
			--data-urlencode "redirect_uri=$REDIRECT_URI" \
			--data-urlencode "grant_type=authorization_code")
		refresh_token=$(json_field refresh_token <<<"$response")
		if [[ -z "$refresh_token" ]]; then
			warn "Google returned no refresh token: $(json_field error_description <<<"$response")"
			exit 1
		fi
		write_env GOOGLE_REFRESH_TOKEN "$refresh_token"
		pause
	fi

	stage "Store the secrets on the $WORKER Worker"
	say "The Worker already lists these secrets; uploading again makes sure they match this token."
	if confirm "Upload ${NAMES[*]} to the $WORKER Worker?"; then
		for name in "${NAMES[@]}"; do
			if printf '%s' "${!name}" | bunx wrangler secret put "$name" --name "$WORKER" >/dev/null; then
				printf '  %s✓ set%s Worker secret %s\n' "$GREEN" "$RESET" "$name"
			else
				SKIPPED+=("Worker secret $name (bunx wrangler secret put $name)")
			fi
		done
		note "A Worker secret applies at once; no deploy needed."
	else
		SKIPPED+=("Worker secrets: re-run the wizard and say yes at stage 5")
	fi
	pause

	stage "Check the app"
	open_url "https://myaccount.google.com/connections"
	step "Open the Journal app entry. It should say 'Access expires: Does not expire'."
	open_url "$APP_URL/session-brief"
	step "The Session brief should start at your last coaching session."
	step "It must not say 'Google Calendar is not connected'."
	if ! confirm "Does the Session brief read the calendar?"; then
		SKIPPED+=("Session brief still can't read the calendar")
	fi

	finish
	say "Next: tell Claude \"the calendar works\" to close #59."
}

run_wizard "$@"
exit
